import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bei 100 KB entscheidet das gewählte Format darüber, wie gut das Bild aussieht. Dasselbe Foto kann in einem Format gestochen scharf und in einem anderen matschig sein.</p>\n<p>JPG, PNG und WebP speichern Bilder jeweils anders. Ihre Stärken zeigen sich deutlich, sobald das Dateibudget knapp wird.</p>\n<p>Dieser Artikel vergleicht alle drei bei 100 KB, damit Sie das richtige für Fotos, Grafiken, Screenshots und Logos wählen können.</p>\n<h2 id=\"how-each-format-works\">Wie jedes Format ein Bild speichert</h2>\n<p>JPG nutzt verlustbehaftete Komprimierung. Es wirft Daten weg, die das Auge kaum bemerkt – deshalb kann es ein Foto so weit schrumpfen.</p>\n<p>PNG nutzt verlustfreie Komprimierung. Es behält jeden Pixel exakt, was für Grafiken perfekt, für Fotos aber teuer ist.</p>\n<p>WebP nutzt moderne verlustbehaftete Komprimierung mit besserer Mathematik als JPG. Es behält bei gleicher Dateigröße mehr Details.</p>\n<p>Bei 100 KB spielen diese Unterschiede eine Rolle. JPG und WebP haben Spielraum zum Arbeiten, PNG oft nicht.</p>\n<h2 id=\"jpg-at-100kb\">JPG bei 100 KB</h2>\n<p>JPG ist das Arbeitstier des Webs. Bei 100 KB behält ein typisches Foto seinen natürlichen Look mit nur geringer Weichheit.</p>\n<p>Hauttöne sind die Stärke von JPG. Es mischt glatte Verläufe sauber, sodass Porträts natürlich statt fleckig wirken.</p>\n<p>Seine Schwäche sind scharfe Kanten. Text und dünne Linien können schwache Halos entwickeln, besonders vor kontrastreichen Hintergründen.</p>\n<p>Die Kompatibilität ist der größte Vorteil von JPG. Jedes Portal, jeder E-Mail-Client und jedes Gerät öffnet JPG ohne Nachdenken.</p>\n<h2 id=\"webp-at-100kb\">WebP bei 100 KB</h2>\n<p>WebP schlägt JPG bei gleicher Dateigröße meist. Kanten bleiben sauberer, Verläufe glatter und feine Details überleben besser.</p>\n<p>Der Vorteil ist bescheiden, aber real. In einem direkten Vergleich bei 100 KB wählen die meisten Menschen die WebP-Version als die schärfere.</p>\n<p>WebP unterstützt außerdem Transparenz, was JPG nicht kann. Das macht es zu einer starken Wahl für Grafiken mit weichen Kanten.</p>\n<p>Der Haken ist die Akzeptanz. Manche älteren Portale, E-Mail-Clients und Behördenformulare lehnen WebP-Dateien noch immer glatt ab.</p>\n<h2 id=\"png-at-100kb\">PNG bei 100 KB</h2>\n<p>PNG ist das falsche Werkzeug für Fotos bei 100 KB. Ein detailreiches Foto, das als PNG gespeichert wird, braucht vielleicht eine Halbierung seiner Abmessungen, nur um zu passen.</p>\n<p>Wo PNG gewinnt, sind Grafiken. Ein Logo, ein Diagramm oder eine Zeichnung mit flachen Farben bleibt in PNG pixelgenau.</p>\n<p>Text ist die andere Stärke von PNG. Scharfe schwarze Buchstaben auf weißem Hintergrund bleiben gestochen scharf, wie JPG es nicht schafft.</p>\n<p>Transparenz ist der letzte Grund, PNG zu wählen. Wenn Ihr Bild einen durchsichtigen Hintergrund braucht, sind PNG oder WebP die einzigen Optionen.</p>\n<h2 id=\"photos-compared\">Fotos bei 100 KB im Vergleich</h2>\n<p>Nehmen Sie ein Porträt. In JPG bei 100 KB sieht das Gesicht natürlich aus und das Haar behält den größten Teil seiner Textur.</p>\n<p>In WebP bei 100 KB sieht dasselbe Porträt etwas schärfer aus. Der Unterschied ist klein, aber er ist da, wenn man genau hinschaut.</p>\n<p>In PNG bei 100 KB scheitert das Porträt. Das Tool muss die Abmessungen stark schrumpfen, um zu passen, und das Ergebnis sieht klein und weich aus.</p>\n<p>Für Fotos ist die Rangfolge klar: WebP zuerst, JPG knapp dahinter und PNG mit großem Abstand zuletzt.</p>\n<h2 id=\"graphics-compared\">Grafiken und Text bei 100 KB im Vergleich</h2>\n<p>Nehmen Sie ein Diagramm mit dünnen Linien und kleinen Beschriftungen. In PNG bleibt jede Linie exakt und jede Beschriftung lesbar.</p>\n<p>In JPG entwickelt dasselbe Diagramm Schmierflecken um den Text. Die Beschriftungen sind noch lesbar, aber sie wirken leicht schmutzig.</p>\n<p>In WebP liegt das Diagramm dazwischen. Es ist sauberer als JPG und für die meisten Grafiken fast so gut wie PNG.</p>\n<p>Für Grafiken dreht sich die Rangfolge um: PNG zuerst, WebP an zweiter Stelle, JPG an dritter. Der Inhaltstyp entscheidet über den Gewinner.</p>\n<h2 id=\"screenshots-compared\">Screenshots bei 100 KB im Vergleich</h2>\n<p>Screenshots mischen Fotos, Text und flache Farben der Benutzeroberfläche. Kein Format ist für alle drei gleichzeitig perfekt.</p>\n<p>PNG hält den Text perfekt, macht die Datei aber riesig. Ein Vollbild-Screenshot in PNG kann mehrere Megabyte groß sein.</p>\n<p>JPG schrumpft den Screenshot problemlos, aber kleiner Text wird weich. Beschriftungen unter 12 Pixeln können schwer lesbar werden.</p>\n<p>WebP ist der beste Kompromiss für Screenshots. Es hält Text weit sauberer als JPG und erreicht trotzdem 100 KB ohne Probleme.</p>\n<h2 id=\"transparency-compared\">Transparenz bei 100 KB</h2>\n<p>Ein Logo mit transparentem Hintergrund kann kein JPG sein. Das Format unterstützt Transparenz überhaupt nicht.</p>\n<p>PNG verarbeitet Transparenz perfekt. Die Kanten bleiben sauber und der Hintergrund bleibt durchsichtig.</p>\n<p>WebP verarbeitet Transparenz ebenfalls, meist bei kleinerer Dateigröße als PNG. Für ein Weblogo ist WebP oft die bessere Wahl.</p>\n<p>Wenn das Ziel ein Portal ist, das nur JPG akzeptiert, müssen Sie die Transparenz zuerst abflachen. Der Hintergrund wird meist weiß.</p>\n<h2 id=\"which-format-when\">Welches Format, wann?</h2>\n<p>Verwenden Sie JPG für Fotos, die an Portale, E-Mails oder ältere Systeme gehen. Es ist die sichere Wahl, die nie abgelehnt wird.</p>\n<p>Verwenden Sie WebP für Fotos und Screenshots auf modernen Websites. Es liefert die beste Qualität pro Kilobyte der drei Formate.</p>\n<p>Verwenden Sie PNG für Logos, Diagramme und Grafiken mit Transparenz. Es ist das einzige Format, das flache Grafiken pixelgenau hält.</p>\n<p>Im Zweifel testen Sie sowohl JPG als auch WebP. Komprimieren Sie dasselbe Bild zweimal und sehen Sie sich beide nebeneinander in der Vorschau an, bevor Sie entscheiden.</p>\n<h2 id=\"testing-method\">Wie Sie Formate selbst testen</h2>\n<p>Wählen Sie ein repräsentatives Bild, nicht Ihr einfachstes. Ein detailreiches Foto mit Text zeigt Formatunterschiede deutlich.</p>\n<p>Komprimieren Sie es mit dem <a href=\"/de/bild-auf-100-kb-komprimieren/\">100-KB-Kompressor</a> in jedem Format auf 100 KB. Halten Sie die Abmessungen identisch, damit der Test fair ist.</p>\n<p>Betrachten Sie alle drei in voller Größe. Zoomen Sie in jeder Version in denselben Bereich hinein und vergleichen Sie dieselben Details.</p>\n<p>Prüfen Sie auch die Dateigrößen. Wenn WebP deutlich unter 100 KB landet, hatte es einen leichteren Job, und der Qualitätsabstand kann größer sein, als er aussieht.</p>\n<ul>\n<li>Fotos für Portale: JPG, für universelle Akzeptanz.</li>\n<li>Fotos für moderne Websites: WebP, für das schärfste Ergebnis.</li>\n<li>Logos und Diagramme: PNG, für pixelgenaue Kanten.</li>\n<li>Screenshots: WebP, für das beste Gleichgewicht.</li>\n<li>Transparente Bilder: PNG oder WebP, niemals JPG.</li>\n</ul>\n<p>Die Formatwahl ist eine kleine Entscheidung mit sichtbarem Ertrag. Investieren Sie zwei Minuten ins Testen, und Ihre 100-KB-Bilder sehen bestmöglich aus.</p>\n<h2 id=\"colour-depth\">Farbtiefe und warum sie bei 100 KB wichtig ist</h2>\n<p>Die Farbtiefe ist die Bandbreite der Farben, die ein Bild zeigen kann. Fotos nutzen Millionen von Farben, während einfache Grafiken vielleicht nur ein paar Hundert verwenden.</p>\n<p>Bei 100 KB vereinfacht der Kompressor Farben, um Platz zu sparen. Glatte Verläufe sind die ersten Opfer, denn sie brauchen viele ähnliche Farbtöne.</p>\n<p>Porträts überstehen das gut, weil Haut eine enge Bandbreite an Tönen nutzt. Ein Gesicht hat weniger Farben als ein Sonnenuntergang, also geht weniger verloren.</p>\n<p>Bunte Szenen leiden stärker. Ein Marktstand mit Dutzenden leuchtender Stoffe braucht mehr Daten, um jeden Farbton getrennt zu halten.</p>\n<p>WebP kommt mit der Farbvereinfachung etwas besser zurecht als JPG. Wenn Ihr Bild sehr bunt ist, versuchen Sie WebP und vergleichen Sie die beiden Ergebnisse.</p>\n<h2 id=\"sharpness-vs-smoothness\">Schärfe vs. Glätte: Die Priorität wählen</h2>\n<p>Jede Komprimierung macht einen Kompromiss zwischen Schärfe und Glätte. Schärfere Bilder halten Kanten klar, zeigen aber mehr Rauschen; glattere Bilder verstecken Rauschen, weichen aber Kanten auf.</p>\n<p>Fotos von Menschen bevorzugen Glätte. Haut sieht etwas weich besser aus als etwas verrauscht, und das Auge verzeiht weiche Haut.</p>\n<p>Text und Grafiken bevorzugen Schärfe. Ein weiches Diagramm ist ein nutzloses Diagramm, Kanten müssen also auch dann klar bleiben, wenn der Hintergrund verrauscht wird.</p>\n<p>Die automatische Qualitätssuche findet von selbst ein gutes Gleichgewicht. Sie wählt die höchste Qualität, die passt – meist genau die richtige Größe für Ihren Inhalt.</p>\n<p>Wenn das automatische Ergebnis falsch wirkt, versuchen Sie das andere Format. JPG neigt zu Glätte, während WebP zu Schärfe neigt, und der Unterschied reicht oft aus.</p>\n<h2 id=\"format-myths\">Formatmythen, die man ignorieren kann</h2>\n<p>Ein Mythos besagt, PNG sei immer hochwertiger als JPG. Das gilt nur für Grafiken; für Fotos bei 100 KB ist PNG weit schlechter.</p>\n<p>Ein anderer Mythos besagt, WebP sehe schlechter aus als JPG. In der Praxis erreicht oder schlägt WebP JPG bei gleicher Dateigröße in fast jedem Test.</p>\n<p>Ein dritter Mythos besagt, das Umwandeln von Formaten ruiniere immer die Qualität. Eine einzige saubere Umwandlung von PNG nach JPG verliert weit weniger, als ein PNG gewaltsam auf 100 KB zu drücken.</p>\n<p>Der beste Weg, diese Fragen zu klären, ist zu testen. Komprimieren Sie dasselbe Bild in jedem Format und vertrauen Sie Ihren eigenen Augen.</p>\n<p>Ihr Inhalt entscheidet über den Gewinner, nicht der Ruf des Formats. Fotos, Grafiken und Screenshots haben jeweils ihr eigenes bestes Format.</p>\n<h2 id=\"archiving-100kb\">Bilder bei 100 KB archivieren</h2>\n<p>Eine 100-KB-Datei ist ein Lieferformat, kein Archivformat. Sie ist zum Hochladen gemacht, nicht zum ewigen Aufbewahren.</p>\n<p>Archivieren Sie das Original in voller Qualität. Eine 100-KB-Kopie lässt sich ohne sichtbaren Schaden weder vergrößern noch drucken noch erneut bearbeiten.</p>\n<p>Verwenden Sie 100-KB-Kopien zum Teilen und Veröffentlichen. Sie laden schnell, bestehen Upload-Grenzen und sehen auf Bildschirmen gut aus.</p>\n<p>Beschriften Sie Archivordner nach Datum und Ereignis. Ein Ordner namens 2026-11-family-trip enthält Originale; die 100-KB-Kopien leben beim Blogbeitrag oder bei der Bewerbung.</p>\n<p>Wenn Sie eine 100-KB-Version erneut brauchen, erstellen Sie sie frisch aus dem Archiv. Komprimieren Sie die alte 100-KB-Kopie nie erneut.</p>\n<h2 id=\"quick-reference\">Kurzreferenz: Formatwahl bei 100 KB</h2>\n<p>Fotos für Portale und E-Mails: JPG. Es wird überall akzeptiert und sieht bei 100 KB sauber aus.</p>\n<p>Fotos für moderne Websites: WebP. Es ist bei gleicher Größe etwas schärfer und hält Seiten leicht.</p>\n<p>Logos, Diagramme und flache Grafiken: PNG. Es hält Kanten pixelgenau und unterstützt Transparenz.</p>\n<p>Screenshots mit Text: zuerst WebP, dann JPG. WebP hält kleinen Text bei 100 KB sauberer.</p>\n<p>Transparente Bilder: nur PNG oder WebP. JPG kann keine Transparenz speichern, es füllt den Hintergrund stattdessen.</p>\n<h2 id=\"lossy-vs-lossless\">Verlustbehaftet vs. verlustfrei: Die Kernidee hinter dem Vergleich</h2>\n<p>Jede Formatentscheidung beginnt mit einer Frage: Ist die Komprimierung verlustbehaftet oder verlustfrei? Die Antwort prägt alles, was folgt.</p>\n<p>Verlustbehaftete Formate wie JPG und WebP werfen Daten dauerhaft weg. Der Verlust ist zunächst unsichtbar und wird dann allmählich sichtbar, je kleiner die Datei wird.</p>\n<p>Verlustfreie Formate wie PNG behalten jeden Pixel exakt. Der Preis ist die Größe: Ein verlustfreies Foto ist oft zehnmal größer als ein verlustbehaftetes.</p>\n<p>Bei 100 KB haben verlustbehaftete Formate Raum, großzügig zu sein. Verlustfreies PNG hat fast keinen Raum, weshalb es bei Fotos versagt.</p>\n<p>Diese eine Unterscheidung zu verstehen, erklärt die meisten Ergebnisse in diesem Artikel. Verlustbehaftet gewinnt bei Fotos, verlustfrei gewinnt bei Grafiken – und der Inhalt entscheidet.</p>\n<h2 id=\"browser-support\">Browser- und Geräteunterstützung für jedes Format</h2>\n<p>JPG funktioniert überall. Jeder Browser, jedes Handy, jeder E-Mail-Client und jeder Drucker der letzten zwanzig Jahre öffnet JPG ohne zweites Nachdenken.</p>\n<p>WebP funktioniert in allen modernen Browsern, einschließlich Chrome, Firefox, Safari und Edge. Ältere Systeme und manche Behördenportale lehnen es allerdings noch ab.</p>\n<p>PNG funktioniert ebenfalls überall. Seine universelle Unterstützung ist ein Grund, warum es als Standard für Logos und Grafiken der Benutzeroberfläche überlebt.</p>\n<p>Wenn das Ziel unbekannt ist, ist JPG die sichere Wahl. Wenn das Ziel eine moderne Website ist, ist WebP meist die bessere Wahl.</p>\n<p>Prüfen Sie das Ziel, bevor Sie wählen. Ein Format, das der Empfänger nicht öffnen kann, ist schlimmer als ein etwas weicheres Bild, das er öffnen kann.</p>\n<h2 id=\"future-formats\">Was kommt nach WebP?</h2>\n<p>Neuere Formate wie AVIF versprechen noch kleinere Dateien als WebP bei gleicher Qualität. Sie sind in Tests beeindruckend, aber noch nicht universell.</p>\n<p>Vorläufig bleibt die praktische Wahl zwischen JPG, PNG und WebP. Diese drei decken jeden echten Bedarf bei 100 KB ab.</p>\n<p>Die AVIF-Unterstützung wächst in Browsern, aber viele Portale und E-Mail-Clients können es noch nicht öffnen. Es heute zu verwenden, riskiert einen abgelehnten Upload.</p>\n<p>Der 100-KB-Kompressor konzentriert sich auf die Formate, die Menschen tatsächlich verwenden können. Wenn AVIF universell wird, erweitert sich die Auswahl.</p>\n<p>Bis dahin beherrschen Sie die drei Formate in diesem Artikel. Sie bewältigen jedes Foto, jede Grafik und jeden Screenshot, den Sie schrumpfen müssen.</p>\n<h2 id=\"how-quality-is-picked\">Wie der Kompressor die Qualität für jedes Format wählt</h2>\n<p>Die automatische Qualitätssuche funktioniert für jedes Format gleich, aber die Ergebnisse unterscheiden sich. JPG und WebP erreichen 100 KB bei höheren Qualitätseinstellungen, als PNG je könnte.</p>\n<p>Bei einem Foto kann sich die Suche nahe 80 Prozent Qualität in JPG und etwas höher in WebP einpendeln. Beide liefern bei diesen Einstellungen saubere Ergebnisse.</p>\n<p>Bei einer Grafik verhält sich die Suche anders. Ein PNG-Diagramm erreicht 100 KB vielleicht erst nach starken Abmessungsschnitten, während dasselbe Diagramm in WebP problemlos passt.</p>\n<p>Das Tool zwingt nicht jedem Bild eine Qualitätszahl auf. Es sucht für jede Datei frisch, weil jedes Bild seine eigene beste Einstellung hat.</p>\n<p>Diese Suche pro Bild ist der Grund, warum das Tool manuelles Raten schlägt. Eine feste Qualität von 70 Prozent wäre für manche Bilder zu hart und für andere zu großzügig.</p>\n<p>Die allgemeine Anleitung finden Sie unter <a href=\"/de/blog/bild-auf-100-kb-komprimieren-anleitung/\">Bild auf 100 KB komprimieren: Die komplette Anleitung</a>. Die Schritte stehen unter <a href=\"/de/blog/bild-auf-100-kb-verkleinern-anleitung/\">Bild auf 100 KB verkleinern: Anleitung</a>. Wenn Sie zuerst zwischen Formaten umwandeln müssen, übernimmt der <a href=\"/de/bilder-konvertieren/\">Bildkonverter</a> diesen Schritt.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Ist WebP bei 100 KB immer besser als JPG?","answer":"Qualitativ meist ja, aber nur etwas. WebP hält Kanten bei gleicher Dateigröße sauberer. Bei der Kompatibilität gewinnt JPG weiterhin, da manche Portale und ältere Systeme WebP ablehnen. Verwenden Sie WebP, wo es akzeptiert wird, und JPG, wo es vielleicht nicht akzeptiert wird."},{"question":"Warum sieht mein Foto als PNG bei 100 KB schlechter aus?","answer":"PNG speichert Bilder ohne Datenverlust, also braucht ein detailreiches Foto weit mehr als 100 KB. Um zu passen, muss das Tool die Abmessungen drastisch schrumpfen, was das Bild klein und weich aussehen lässt. PNG ist für Grafiken gemacht, nicht für Fotos."},{"question":"Kann ich ein PNG-Foto in JPG umwandeln, um 100 KB zu erreichen?","answer":"Ja, und es funktioniert meist gut. Ein Foto von PNG in JPG umzuwandeln, ist der schnellste Weg, 100 KB mit guter Qualität zu erreichen. Vermeiden Sie es nur, wenn das Bild Transparenz braucht, denn JPG kann keinen transparenten Hintergrund speichern."},{"question":"Behält WebP dieselben Farben wie JPG?","answer":"Ja, bei normalen Fotos stimmen die Farben eng überein. WebP kann etwas glattere Verläufe speichern, was Farben manchmal sauberer aussehen lässt. Jeder Unterschied ist subtil und kommt von der besseren Komprimierung, nicht von einer Farbänderung."},{"question":"Welches Format soll ich für ein eingescanntes Dokument bei 100 KB verwenden?","answer":"JPG funktioniert bei eingescannten Dokumenten mit 100 KB meist am besten, weil Scans sich wie Fotos verhalten. Wenn das Dokument hauptsächlich schwarzen Text auf Weiß ohne Fotos enthält, hält PNG den Text schärfer, aber die Datei braucht vielleicht kleinere Abmessungen, um zu passen."},{"question":"Verringert das Umwandeln von Formaten meine Bildqualität?","answer":"Die Umwandlung von PNG in JPG oder WebP ist ein verlustbehafteter Schritt, also geht etwas Qualität verloren. Aber von einem hochwertigen PNG auszugehen und einmal umzuwandeln, liefert ein weit besseres Ergebnis, als das PNG selbst gewaltsam auf 100 KB zu drücken. Eine saubere Umwandlung schlägt ein gequetschtes PNG."}];
